-- Original noncombat NPC positions; no inferred dialogue roots or actions.
CREATE TABLE world_native_npc_placements (
 actor_id bigint PRIMARY KEY CHECK(actor_id BETWEEN -9007199254740991 AND -1),
 reference_id smallint NOT NULL CHECK(reference_id>0),
 map_id integer NOT NULL CHECK(map_id>0), instance_id bigint NOT NULL DEFAULT 0 CHECK(instance_id=0),
 x integer NOT NULL, y integer NOT NULL, z smallint NOT NULL,
 direction smallint NOT NULL CHECK(direction BETWEEN 0 AND 7),
 name_es text NOT NULL CHECK(length(name_es)>0), visual_id integer NOT NULL CHECK(visual_id>0),
 level smallint NOT NULL CHECK(level>0), native_action_ids jsonb NOT NULL CHECK(jsonb_typeof(native_action_ids)='array'),
 source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[a-f0-9]{64}$'),
 source_frame integer NOT NULL CHECK(source_frame>=0), provenance text NOT NULL,
 enabled boolean NOT NULL DEFAULT true,
 UNIQUE(map_id,instance_id,x,y,z)
);
